"use strict";(self.webpackChunkizakharau_blog_docusaurus=self.webpackChunkizakharau_blog_docusaurus||[]).push([[8871],{4582:(e,t,n)=>{n.d(t,{A:()=>i});const i=n.p+"assets/images/part2-1-4d42149ad558b7f6e144a1cffae9af19.png"},4660:(e,t,n)=>{n.d(t,{A:()=>i});const i=n.p+"assets/images/part2-3-c223cad4b29db9497a9509ce7b48dd3a.png"},4760:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>r,default:()=>d,frontMatter:()=>o,metadata:()=>i,toc:()=>c});const i=JSON.parse('{"id":"replacing-legacy/replacing-legacy-2","title":"Archeology, Politics, Red Flags","description":"In this part, we cover one of the approaches for modernization and possible caveats.","source":"@site/docs/replacing-legacy/replacing-legacy-2.md","sourceDirName":"replacing-legacy","slug":"/replacing-legacy/replacing-legacy-2","permalink":"/essays/replacing-legacy/replacing-legacy-2","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"authors":["ilya"],"slug":"replacing-legacy-2"},"sidebar":"tutorialSidebar","previous":{"title":"Definition, Reasons, Characteristics","permalink":"/essays/replacing-legacy/replacing-legacy-1"},"next":{"title":"Conversion & Data Mapping","permalink":"/essays/replacing-legacy/replacing-legacy-3"}}');var s=n(4848),a=n(8453);const o={authors:["ilya"],slug:"replacing-legacy-2"},r="Archeology, Politics, Red Flags",l={},c=[{value:"You can&#39;t repeat the past",id:"you-cant-repeat-the-past",level:2},{value:"Deconstructing the Colossus",id:"deconstructing-the-colossus",level:2},{value:"Let&#39;s talk about politics",id:"lets-talk-about-politics",level:2},{value:"Red flags",id:"red-flags",level:2},{value:"Closing thoughts to Part 2",id:"closing-thoughts-to-part-2",level:2}];function h(e){const t={a:"a",h1:"h1",h2:"h2",header:"header",hr:"hr",img:"img",li:"li",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"archeology-politics-red-flags",children:"Archeology, Politics, Red Flags"})}),"\n",(0,s.jsx)(t.p,{children:"In this part, we cover one of the approaches for modernization and possible caveats."}),"\n",(0,s.jsx)(t.p,{children:"Legacy systems usually have a monolithic structure with several layers of business logic added throughout the years of operation. And the microservice architecture is a modern response to the old lavish monolith. As there is no sense in replacing a monolith with another monolith, right?"}),"\n",(0,s.jsx)(t.p,{children:'Such a pattern generally implies "eating an elephant by pieces": step-by-step re-implementing the functionality to transition from an old to a new system. But do we need to bring the old mess to the new home? That is the critical question to answer.'}),"\n",(0,s.jsx)(t.h2,{id:"you-cant-repeat-the-past",children:"You can't repeat the past"}),"\n",(0,s.jsx)(t.p,{children:"There are two undeniable statements:"}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsx)(t.li,{children:"The new system can't do something exactly like the old one. You will not create the exact copy even if you try hard to achieve a 100% match. You will get a different system anyway."}),"\n",(0,s.jsx)(t.li,{children:"There is no sense for the new system to act exactly like the old one. You most likely need some help understanding what you are doing if replicating the full functionality."}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:"For instance, the Legacy's Entity structure might be outdated and not match the current business domain. The entire data definition needs to be revised so that some entities will no longer possess the attributes they had, and some will no longer exist. So, the user and application interfaces are also the subject of complete revisions."}),"\n",(0,s.jsx)(t.p,{children:'A Business Analyst is usually involved in what I call "Software archeology." The context between now and then shifted or was missed entirely. The responsible people left or forgot many details. No one knows why some features or logic were added and if it is utilized now or ever. You can spend time investigating the reasoning and end up with nothing. In this case, there are two ways: bring that into the new system (just in case) or cut that functionality and\xa0see if that will hurt someone. The second option might be painful and consequential, so be cautious.'}),"\n",(0,s.jsx)(t.h2,{id:"deconstructing-the-colossus",children:"Deconstructing the Colossus"}),"\n",(0,s.jsx)(t.p,{children:"If we are talking about a backend legacy, which multiple consumers use via API, the best strategy is to:"}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsx)(t.li,{children:"Wrap the Legacy with the new API layer (API Gateway), replicating the current payload and bringing the new data format or API type (e.g., XML to JSON, SOAP to RESTful API, etc)."}),"\n",(0,s.jsx)(t.li,{children:"Make the data conversion happen in that new layer, so the Legacy still works with its data structure, but now it is detached from the consumers."}),"\n",(0,s.jsx)(t.li,{children:"Make consumers migrate to call the Gateway instead of the Legacy directly. Be persistent and, at some point, cut the possibility of calling it directly. However, there is a must-have condition: the data conversion should work ideally without any performance concerns."}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.img,{alt:"One of the slides I used in my 2019 and 2023 speeches on this topic",src:n(4582).A+"",width:"960",height:"540"})}),"\n",(0,s.jsx)(t.p,{children:"Data mapping and conversion is a massive topic on its own. It is challenging to manage the mapping of multiple huge entities between two formats. But if there is a three format, the conversion complexity doubles if not triples. Especially if you don't own all the structures."}),"\n",(0,s.jsx)(t.hr,{}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.img,{alt:"One of the slides I used in my 2019 and 2023 speeches on this topic",src:n(5789).A+"",width:"960",height:"540"})}),"\n",(0,s.jsx)(t.p,{children:"The Team was working on the conversion between the legacy format and input/output JSON for Microservices API. But there was already a 3rd structure used by a Client with the existing conversion from Legacy to XML and vice versa. XML was not 100% equal to the Legacy structure and had unique data definitions."}),"\n",(0,s.jsx)(t.p,{children:"So that looks like Legacy -> XML -> JSON and reverse JSON -> XML -> Legacy. Supporting that kind of conversion was hell for the Team. They did a direct conversion between Legacy and JSON. However, the Client did not agree to migrate, so the transformation was challenging to maintain because both structures were fluent and constantly changed by different teams."}),"\n",(0,s.jsx)(t.hr,{}),"\n",(0,s.jsxs)(t.p,{children:["The most important thing is to have a\xa0",(0,s.jsx)(t.strong,{children:"technical vision"}),"\xa0of how the Legacy will be decomposed. More than just a deck with a few fancy diagrams is required."]}),"\n",(0,s.jsx)(t.p,{children:"Assuming we have the API layer and conversion layers.\xa0Before we move to the actual decomposition, we need to have a testing strategy: how will we ensure that the new system does not regress compared to the monolith?"}),"\n",(0,s.jsx)(t.p,{children:"A solution is to have an orchestrator that calls the new and old systems and then compares the outcomes. API layer can handle the first, and the testing service can do the latter. That will allow you to track and address possible degradation of the client experience (and catch bugs)."}),"\n",(0,s.jsx)(t.p,{children:"Now that we have the API layer, conversion, and testing service, we can start cutting off monolith pieces and re-implement them as microservices. Doing it purely Agile without prior comprehensive system analysis can turn sour."}),"\n",(0,s.jsx)(t.p,{children:"What is lying on the surface is the low-hanging fruit. However, moving further and deeper might change the previous design and make further decomposition much harder."}),"\n",(0,s.jsx)(t.h2,{id:"lets-talk-about-politics",children:"Let's talk about politics"}),"\n",(0,s.jsx)(t.p,{children:"Internal politics is also a reason why delivering the result soon is critical, not waiting until you finish the decomposition. If you have an intermediate result sufficient to cover some logic handled without monolith, you must push it to Production. First, it is a good (but painful) experience. Second, it is difficult to cancel a project that is already in Production and used by customers."}),"\n",(0,s.jsx)(t.p,{children:"It is inevitable that some of the resources you had from the start will be drawn from you and reallocated to other business priorities. Or you will not be given enough resources constantly. So, from the beginning, there should be a releasing strategy. Not in a distant future, desirably."}),"\n",(0,s.jsx)(t.hr,{}),"\n",(0,s.jsx)(t.p,{children:'The Engineering Manager pushed the Team to launch a few already decomposed microservices along with the "wrapped" monolith for a Client product on a significant market. Those services were quite raw, so that was a challenging release with much effort spent on support.'}),"\n",(0,s.jsx)(t.p,{children:"That seemed an unjustified effort, and the Team would instead focus on stabilization and further decomposition. But now I see that the manager was right, and it was necessary to do that release to demonstrate the progress and keep going."}),"\n",(0,s.jsx)(t.hr,{}),"\n",(0,s.jsxs)(t.p,{children:['There is a temptation to introduce some decomposed pieces as a new application with enhanced capabilities previously not seen in the monolith. I call them Sidekicks, and they can outshine the "parent" product and shift the main focus to chasing a quick profit. I covered that topic in a\xa0',(0,s.jsx)(t.a,{href:"https://izakharau.me/posts/sidekick-product/",children:"different essay"}),"\xa0available on my blog."]}),"\n",(0,s.jsx)(t.p,{children:"Such replacement is a money-consuming endeavor with no evident profits in the foreseeable future. It is a hard sell for the executive management. Having a new exited application is a trick to start chasing quick money instead of focusing the resources on the legacy replacement."}),"\n",(0,s.jsx)(t.h2,{id:"red-flags",children:"Red flags"}),"\n",(0,s.jsx)(t.p,{children:"To name a few signs when something goes wrong or will likely go wrong in the future:"}),"\n",(0,s.jsxs)(t.ol,{children:["\n",(0,s.jsx)(t.li,{children:"Legacy system components are owned by different teams without a single Leadership."}),"\n",(0,s.jsx)(t.li,{children:'The "Legacy" and the "Replacement" are different teams under different management.'}),"\n",(0,s.jsx)(t.li,{children:"The source code of a Legacy is missed, or the Replacement Team cannot access it."}),"\n",(0,s.jsx)(t.li,{children:"Some Legacy documentation cannot be shared with the Replacement Team due to various concerns."}),"\n",(0,s.jsx)(t.li,{children:"Develop the Sidekicks (see above) in parallel."}),"\n",(0,s.jsx)(t.li,{children:'"Deal with it later" attitude toward the next steps.'}),"\n",(0,s.jsx)(t.li,{children:"Frequent changes in the technology stack: frequent migration to different CI/CD tools, libraries, frameworks, and databases (e.g., MongoDB to PostgreSQL)."}),"\n"]}),"\n",(0,s.jsx)(t.h2,{id:"closing-thoughts-to-part-2",children:"Closing thoughts to Part 2"}),"\n",(0,s.jsx)(t.p,{children:'We all know that the system exists only to satisfy the needs of higher systems (to simplify things, we call it "the Business"). And we also know that there are multiple ways to satisfy those needs. It is about making the right choice when answering the "how" question. People behind a Legacy system once made their choice. Time proved whether they were right about something or not.'}),"\n",(0,s.jsx)(t.p,{children:"People behind the new system need to make their own calculated choices based on the context and environment where an organization currently exists. They only need the required time, resources, competence, and dedication. Not so much, right?"}),"\n",(0,s.jsx)(t.p,{children:"In the end, here is my favorite picture on this topic:"}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.img,{alt:"Big piece of shit splitted into small pieces of shit",src:n(4660).A+"",width:"1200",height:"683"})})]})}function d(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(h,{...e})}):h(e)}},5789:(e,t,n)=>{n.d(t,{A:()=>i});const i=n.p+"assets/images/part2-2-b2c679f65075f78f06e946d60343cb9a.png"},8453:(e,t,n)=>{n.d(t,{R:()=>o,x:()=>r});var i=n(6540);const s={},a=i.createContext(s);function o(e){const t=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:o(e.components),i.createElement(a.Provider,{value:t},e.children)}}}]);